css:
.print-format {
    padding: 15px !important;
}

body {
    color: #000;
    margin: 0;
}

body * {
    font-family: Calibri, Arial, sans-serif;
    font-size: 10px;
    line-height: 1.5em;
    box-sizing: border-box;
}

.logo-wrap {
    text-align: center;
    margin-bottom: 8px;
}

.logo {
    max-width: 90px;
    max-height: 60px;
}

.doc-title {
    font-size: 20px;
    font-weight: bold;
    padding: 8px 0 10px 6px;
}

table.outer {
    width: 100%;
    border: none;
    margin-bottom: 18px;
}

table.outer td {
    vertical-align: top;
    padding: 4px 8px;
}

.no-border,
.no-border td,
.no-border th {
    border: none !important;
}

.left-info,
.right-info {
    width: 50%;
}

.left-info div,
.right-info div {
    margin-bottom: 3px;
}

.data-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 10px;
}

.data-table th,
.data-table td {
    border: 1px solid #000;
    padding: 6px !important;
    text-align: center;
}

.data-table th {
    background-color: #f5f5f5;
    font-weight: bold;
}

.text-left {
    text-align: left !important;
}

.items-table {
    margin-top: 8px;
}

.totals-row td {
    height: 28px;
}

.label-cell {
    font-weight: bold;
}

.summary-table {
    margin-top: 40px;
}

.terms {
    font-size: 12px;
    text-align: center;
    margin-top: 28px;
    padding-top: 10px;
    line-height: 1.8;
}

.footer {
    border-top: 2px solid #000;
    font-size: 10px;
    text-align: center;
    margin-top: 50px;
    padding-top: 8px;
    line-height: 1.6;
}
